import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js';

const $=s=>document.querySelector(s), root=$('#game-root');
const scene=new THREE.Scene(); scene.background=new THREE.Color(0x9db5b2); scene.fog=new THREE.Fog(0x9db5b2,36,125);
const camera=new THREE.PerspectiveCamera(73,innerWidth/innerHeight,.08,220); camera.rotation.order='YXZ';
const renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance'}); renderer.setSize(innerWidth,innerHeight); renderer.setPixelRatio(Math.min(devicePixelRatio,1.65)); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap; renderer.outputColorSpace=THREE.SRGBColorSpace; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.08; root.appendChild(renderer.domElement);
const hemi=new THREE.HemisphereLight(0xdce9e2,0x41483d,1.75); scene.add(hemi);
const sun=new THREE.DirectionalLight(0xffe2b9,3.2); sun.position.set(-25,38,22); sun.castShadow=true; sun.shadow.mapSize.set(1024,1024); sun.shadow.camera.left=-42; sun.shadow.camera.right=42; sun.shadow.camera.top=42; sun.shadow.camera.bottom=-42; scene.add(sun);
const mats={ground:new THREE.MeshStandardMaterial({color:0x777e70,roughness:1}), asphalt:new THREE.MeshStandardMaterial({color:0x343b3b,roughness:.92}), concrete:new THREE.MeshStandardMaterial({color:0x7e8980,roughness:.8}), steel:new THREE.MeshStandardMaterial({color:0x56656a,metalness:.78,roughness:.34}), darkSteel:new THREE.MeshStandardMaterial({color:0x273337,metalness:.74,roughness:.42}), yellow:new THREE.MeshStandardMaterial({color:0xd9a52d,metalness:.35,roughness:.5}), cream:new THREE.MeshStandardMaterial({color:0xd1d4c8,roughness:.75}), glass:new THREE.MeshStandardMaterial({color:0x24434a,metalness:.3,roughness:.22,emissive:0x102124}), green:new THREE.MeshStandardMaterial({color:0x59775a,roughness:.78}), rust:new THREE.MeshStandardMaterial({color:0x8c5637,roughness:.7}), lime:new THREE.MeshStandardMaterial({color:0xc8f36a,emissive:0x4d7724,emissiveIntensity:.7}), red:new THREE.MeshStandardMaterial({color:0xd7563d,emissive:0x4a1209})};
function box(x,y,z,sx,sy,sz,mat,shadow=true){const m=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),mat);m.position.set(x,y,z);m.castShadow=shadow;m.receiveShadow=true;scene.add(m);return m}
function cyl(x,y,z,r1,r2,h,mat,seg=16){const m=new THREE.Mesh(new THREE.CylinderGeometry(r1,r2,h,seg),mat);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;scene.add(m);return m}
function line(a,b,mat=mats.steel,r=.055){const A=new THREE.Vector3(...a),B=new THREE.Vector3(...b),d=new THREE.Vector3().subVectors(B,A);const m=new THREE.Mesh(new THREE.CylinderGeometry(r,r,d.length(),8),mat);m.position.copy(A).add(B).multiplyScalar(.5);m.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),d.normalize());m.castShadow=true;scene.add(m);return m}
function label(text,x,y,z,color='#d3e2d4',size=.18){const c=document.createElement('canvas');c.width=512;c.height=128;const ctx=c.getContext('2d');ctx.fillStyle='rgba(8,15,16,.76)';ctx.fillRect(0,0,512,128);ctx.font='bold 34px monospace';ctx.fillStyle=color;ctx.fillText(text,20,78);const tx=new THREE.CanvasTexture(c);const m=new THREE.Mesh(new THREE.PlaneGeometry(size*5,size*1.25),new THREE.MeshBasicMaterial({map:tx,transparent:true,side:THREE.DoubleSide}));m.position.set(x,y,z);m.rotation.y=Math.PI;m.userData.isLabel=true;scene.add(m);return m}
// remote field and service apron
box(0,-.42,0,190,.7,190,mats.ground,false);box(0,-.025,0,58,.12,48,mats.concrete,false);box(-5,.035,0,8,.08,42,mats.asphalt,false);box(7,.035,-6,32,.08,7,mats.asphalt,false);
for(let i=-19;i<21;i+=2){box(-5,.09,i,.09,.015,.85,new THREE.MeshStandardMaterial({color:0xc4b88e}),false)}
// perimeter fencing, posts and amber hazard strobes
for(let x=-28;x<=28;x+=4){cyl(x,.75,-22,.065,.065,1.5,mats.darkSteel,8);cyl(x,.75,22,.065,.065,1.5,mats.darkSteel,8)}
for(let z=-22;z<=22;z+=4){cyl(-28,.75,z,.065,.065,1.5,mats.darkSteel,8);cyl(28,.75,z,.065,.065,1.5,mats.darkSteel,8)}
for(const z of [-22,22]){box(0,.4,z,56,.055,.055,mats.steel,false);box(0,1.05,z,56,.045,.045,mats.steel,false)}for(const x of [-28,28]){box(x,.4,0,.055,.055,44,mats.steel,false);box(x,1.05,0,.045,.045,44,mats.steel,false)}
for(const [x,z] of [[-25,-18],[25,-18],[-25,18],[25,18]]){cyl(x,2.1,z,.05,.05,4,mats.darkSteel,8);cyl(x,4.2,z,.24,.24,.18,mats.yellow,12);const l=new THREE.PointLight(0xffbf72,1.5,13);l.position.set(x,3.8,z);scene.add(l)}
// main K-9 bore rig: base, derrick truss, hoist and rotary head
box(0,.32,0,8.5,.55,7.2,mats.darkSteel);box(0,.64,0,7.8,.12,6.6,mats.yellow);
const rigTopY=11.3; for(const x of [-2.7,2.7]){line([x,.72,-2.45],[x*.65,rigTopY,-2.45],mats.steel,.12);line([x,.72,2.45],[x*.65,rigTopY,2.45],mats.steel,.12)}
for(let y=1.1;y<=10.5;y+=1.35){const w=5.4-(y/11)*1.5;line([-w/2,y,-2.45],[w/2,y,-2.45],mats.steel,.07);line([-w/2,y,2.45],[w/2,y,2.45],mats.steel,.07);line([-w/2,y,-2.45],[w/2,y+1.35,-2.45],mats.yellow,.045);line([w/2,y,-2.45],[-w/2,y+1.35,-2.45],mats.yellow,.045);line([-w/2,y,2.45],[w/2,y+1.35,2.45],mats.steel,.045);line([w/2,y,2.45],[-w/2,y+1.35,2.45],mats.steel,.045)}
box(0,11.35,0,2.35,.65,2.25,mats.yellow);box(0,11.74,0,1.45,.22,1.5,mats.darkSteel);const rotary=cyl(0,10.15,0,.8,.8,.55,mats.steel,24);rotary.rotation.y=.3;
const pipe=cyl(0,5.6,0,.27,.27,9.3,mats.darkSteel,20);const drillHead=cyl(0,.9,0,.76,.34,1,mats.steel,18);drillHead.rotation.x=Math.PI;
for(let i=0;i<8;i++){const a=i*Math.PI/4;line([Math.cos(a)*.25,.25,Math.sin(a)*.25],[Math.cos(a)*.9,1.35,Math.sin(a)*.9],i%2?mats.steel:mats.yellow,.06)}
// top service platform and walkable access ramp
box(0,10.15,0,5.7,.16,5.4,mats.darkSteel);for(const x of [-2.65,2.65])box(x,10.45,0,.08,.55,5.2,mats.yellow);
// visible stair run climbing rig, plus walkable inclined service walkway
for(let i=0;i<12;i++){const z=3.4-i*.38,y=.15+i*.19;box(2.85,y,z,1.2,.12,.43,i%2?mats.steel:mats.darkSteel);line([2.2,y+.2,z],[2.2,y+.2,z-.38],mats.yellow,.035);line([3.5,y+.2,z],[3.5,y+.2,z-.38],mats.yellow,.035)}
const ramp=new THREE.Mesh(new THREE.BoxGeometry(1.05,.08,4.6),new THREE.MeshStandardMaterial({color:0x667274,transparent:true,opacity:.001}));ramp.position.set(2.85,1.13,1.05);ramp.rotation.x=-.48;scene.add(ramp);
// oil reservoir, hydraulic pistons, engine, radiator, pipe details
const tank=cyl(3.2,1.75,-1.3,.77,.77,2.3,mats.yellow,20);tank.rotation.z=Math.PI/2;for(let x=2.6;x<=3.8;x+=.3)cyl(x,2.55,-1.3,.085,.085,.13,mats.darkSteel,10);
box(-2.2,1.25,1.1,2.1,1.4,2,mats.darkSteel);box(-2.2,2,1.1,1.75,.15,1.6,mats.steel);for(let i=0;i<7;i++)box(-3.28+i*.3,1.25,.08,.09,.9,.09,mats.yellow);
for(const x of [-1.4,1.4]){line([x,.95,1.5],[x,3.4,1.5],mats.yellow,.14);line([x,.95,1.7],[x,3.4,1.7],mats.steel,.06)}
for(let i=0;i<5;i++)cyl(3.9,1.2+i*.27,1.5,.09,.09,.14,mats.steel,12).rotation.z=Math.PI/2;
// control console, gauges and status beacons
box(3.15,1.1,3.3,1.65,1.8,.7,mats.darkSteel);box(3.15,1.85,2.92,1.35,.68,.12,mats.glass);for(let x of [2.7,3.15,3.6]){cyl(x,1.38,2.91,.105,.105,.1,mats.red,12);cyl(x,1.08,2.91,.08,.08,.1,mats.lime,12)}
label('K-9  /  CONTROL',3.2,2.7,2.89,'#c8f36a',.19);label('OIL  /  REFILL',.4,3.3,-.25,'#f3c35b',.2);
for(const [x,z] of [[-3.1,-3],[3.1,-3],[-3.1,3],[3.1,3]]){box(x,3.9,z,.12,.12,.12,mats.yellow);const beacon=new THREE.PointLight(0xffb54a,.4,4);beacon.position.set(x,4,z);scene.add(beacon)}
// open bore, layered rim and luminous geological shaft
cyl(0,-.02,0,1.65,1.65,.18,mats.darkSteel,32);cyl(0,-.13,0,1.28,1.28,.04,new THREE.MeshStandardMaterial({color:0x080e11,roughness:.2}),32);for(let y=-.2;y>-5;y-=.7){const r=1.18+(-y)*.045;const ring=new THREE.Mesh(new THREE.TorusGeometry(r,.08,8,32),new THREE.MeshStandardMaterial({color:y<-2?0xa35b37:0x584d3d,roughness:.9}));ring.rotation.x=Math.PI/2;ring.position.y=y;scene.add(ring)}
// portable site objects and clearly marked safety zones
for(let i=0;i<6;i++){const x=-5+i*1.1;box(x,.22,-4,.78,.42,.65,i%2?mats.yellow:mats.darkSteel);cyl(x,.55,-4,.1,.1,.15,mats.steel,10)}
for(const [x,z] of [[-4,-1],[4,-1],[-4,1],[4,1]]){box(x,.08,z,.06,.02,.7,mats.yellow,false)}
function building(x,z,w,d,h,wall,sign){box(x,h/2,z,w,h,d,wall);box(x,h+.07,z,w+.22,.15,d+.2,mats.darkSteel);for(const side of [-1,1]){box(x+side*(w/2+.015),h*.55,z,.05,.08,d-.45,mats.yellow,false)}
// front wall split to leave a generous walk-in doorway
box(x-w*.27,h*.46,z+d/2,w*.46,h*.92,.17,wall);box(x+w*.27,h*.46,z+d/2,w*.46,h*.92,.17,wall);box(x,h*.94,z+d/2,w*.12,.12,.18,mats.yellow);box(x,h*.98,z+d/2,w*.94,.22,.28,mats.yellow);box(x,h+.17,z+d/2,w*.9,.12,.08,mats.steel);label(sign,x,h*.92,z+d/2+.1,'#e1edce',.21);}
building(8,-6,10,7,3.5,mats.cream,'GEOLOGY  /  LAB');building(13,2,7,6,3,mats.green,'LUBE  /  SUPPLY');
// interior floor clear and lab bench / screens
for(const x of [5.4,7.1,9.0,10.4]){box(x,.72,-7.3,1.15,1.4,.15,mats.darkSteel);box(x,.86,-7.19,.88,.62,.06,mats.glass);box(x,.13,-6.8,1.5,.22,.65,mats.steel);for(const z of [-8.35])box(x,.94,z,.15,.35,.15,mats.yellow)}
box(8,1.25,-8.78,4.2,1.55,.18,mats.darkSteel);for(let i=0;i<3;i++){box(6.6+i*1.35,1.25,-8.65,1.2,1.18,.08,mats.glass);box(6.6+i*1.35,1.25,-8.59,1.05,.86,.025,new THREE.MeshBasicMaterial({color:[0x244b48,0x384955,0x3e5442][i]}))}
// research rocks and microscope props
for(let i=0;i<5;i++){const r=cyl(5.2+i*1.25,.52,-5.7,.28,.32,.5,[mats.rust,mats.yellow,mats.steel,mats.green,mats.darkSteel][i],8);r.rotation.z=.16}
// shop counter, shelves, barrels, shopkeeper silhouette
box(13,1,1.5,3.7,1.05,.65,mats.darkSteel);box(13,1.58,1.13,3.75,.16,.13,mats.yellow);for(const x of [10.5,11.4,14.4,15.2]){box(x,1.35,-.1,.12,2.4,.15,mats.steel);box(x,1.9,-.08,.85,.1,1.4,mats.yellow);box(x,.9,-.08,.85,.1,1.4,mats.steel)}
for(const [x,z,mat] of [[10.9,-.1,mats.rust],[12,-.1,mats.green],[14.5,-.1,mats.yellow],[15.1,1,mats.rust]]){cyl(x,.62,z,.34,.34,1.05,mat,16);cyl(x,1.18,z,.36,.36,.09,mats.darkSteel,16)}
// shopkeeper simple human figure
cyl(13.2,1.25,.8,.22,.22,.65,mats.green,12);const head=cyl(13.2,1.77,.8,.18,.18,.28,mats.cream,12);box(13.2,1.46,.8,.46,.54,.32,mats.green);
// warehouses, loading equipment and parked service vehicle
building(-12,-7,11,8,4,mats.darkSteel,'CORE  /  STORAGE');for(let i=0;i<5;i++){box(-15+i*1.35,.8,-7,1.05,1.5,.95,i%2?mats.rust:mats.yellow);box(-15+i*1.35,1.62,-7,1.09,.12,.99,mats.darkSteel)}
box(-13,.62,8,5.5,1.1,2.5,mats.yellow);box(-12.2,1.48,8,.9,.62,2.35,mats.glass);for(const x of [-15,-11])for(const z of [7,9])cyl(x,.28,z,.35,.35,.18,mats.darkSteel,12).rotation.z=Math.PI/2;
// camera poles and labels
for(const [x,z] of [[-4,-4],[15,5],[5,-2],[-16,-2],[-20,1]]){cyl(x,2.5,z,.055,.055,4.8,mats.darkSteel,8);box(x,4.85,z,.38,.2,.3,mats.steel);box(x,4.85,z-.15,.16,.1,.08,mats.red)}
// distant ridge silhouettes, scrub and overhead moving cloud banks
for(let i=0;i<34;i++){const x=(Math.random()-.5)*140,z=-45-Math.random()*38,r=3+Math.random()*9;const hill=new THREE.Mesh(new THREE.ConeGeometry(r,4+Math.random()*8,7),new THREE.MeshStandardMaterial({color:i%2?0x718078:0x65746d,roughness:1}));hill.position.set(x,1,z);hill.rotation.y=Math.random()*6;scene.add(hill)}
const clouds=[];for(let i=0;i<18;i++){const g=new THREE.Group();const mat=new THREE.MeshBasicMaterial({color:0xe2e4da,transparent:true,opacity:.24,depthWrite:false});for(let j=0;j<4;j++){const c=new THREE.Mesh(new THREE.SphereGeometry(1,10,8),mat);c.scale.set(2.6+Math.random()*2,.28+Math.random()*.25,1.1);c.position.set((j-1.5)*1.8,Math.random()*.25,Math.random()*.7);g.add(c)}g.position.set((Math.random()-.5)*100,18+Math.random()*8,(Math.random()-.5)*95);g.userData.speed=.12+Math.random()*.18;scene.add(g);clouds.push(g)}

