const defaults={depth:0,money:1250,oil:68,capacity:100,drilling:false,resources:{Coal:0,Iron:0,Copper:0,Gold:0,Diamonds:0,'Rare minerals':0},upgrades:{power:0,speed:0,engine:0,durability:0,capacity:0,efficiency:0,cooling:0,maintenance:0,heat:0,pressure:0,deep:0,scanner:0},can:0,discovered:[],milestones:[],totalDrilled:0};
let state={...defaults};try{const saved=JSON.parse(localStorage.getItem('earthcore-save')||'null');if(saved)state={...defaults,...saved,resources:{...defaults.resources,...saved.resources},upgrades:{...defaults.upgrades,...saved.upgrades}}}catch{}
let yaw=0,pitch=0,keys={},nearby=null,modalOpen=false,toastTimer=0,drillTime=0,resourceCheck=0,dayTime=.31,soundOn=true,audioCtx=null,engineOsc=null;const player={x:3,z:7,y:0,speed:4.1,sprint:false,locked:false,joyX:0,joyY:0};
camera.position.set(player.x,1.66,player.z);
const layers=[{d:0,n:'SURFACE SOIL',m:'Mineral soil',color:'#b6ad8d'},{d:100,n:'CLAY & LIMESTONE',m:'Clay / limestone',color:'#c6b98c'},{d:500,n:'HARD STONE',m:'Basaltic stone',color:'#9a9287'},{d:1000,n:'COAL SEAM',m:'Carboniferous coal',color:'#757d76'},{d:2000,n:'IRON DEPOSITS',m:'Banded iron formation',color:'#9c6042'},{d:4000,n:'GOLD VEIN',m:'Auriferous quartz',color:'#ccaa57'},{d:6000,n:'RARE MINERALS',m:'Pegmatite / rare earths',color:'#817db2'},{d:10000,n:'DEEP CRUST',m:'Lower continental crust',color:'#805345'},{d:20000,n:'UPPER MANTLE*',m:'Peridotite mantle analogue',color:'#be6746'},{d:100000,n:'LOWER MANTLE*',m:'High-pressure silicate',color:'#d27b44'},{d:1000000,n:'OUTER CORE*',m:'Liquid iron-nickel analogue',color:'#dc7043'},{d:6371000,n:'INNER CORE*',m:'Solid iron-nickel analogue',color:'#f1c15e'}];
const resources=[['Coal',24],['Iron',42],['Copper',58],['Gold',180],['Diamonds',420],['Rare minerals',260]];
const upgrades=[
 {id:'power',name:'Drill power',desc:'More torque for resistant rock formations.',base:480,stat:'+18% penetration force'}, {id:'speed',name:'Rotary speed',desc:'Higher bit RPM improves advance rate.',base:390,stat:'+15% drilling speed'}, {id:'engine',name:'Engine output',desc:'Reinforced drive train for sustained load.',base:560,stat:'+12% overall output'}, {id:'durability',name:'Bit durability',desc:'Longer-lived cutters reduce service stops.',base:330,stat:'−12% equipment wear'}, {id:'capacity',name:'Oil capacity',desc:'Install a larger reservoir and sight gauge.',base:420,stat:'+35 L tank capacity'}, {id:'efficiency',name:'Oil efficiency',desc:'Precision metering cuts lubricant use.',base:520,stat:'−16% oil consumption'}, {id:'cooling',name:'Cooling system',desc:'Industrial heat exchanger for downhole work.',base:490,stat:'−10% operating temperature'}, {id:'maintenance',name:'Auto maintenance',desc:'Predictive sensors protect moving components.',base:640,stat:'−10% wear / fault risk'}, {id:'heat',name:'Heat resistance',desc:'Ceramic insulation for hot formations.',base:950,stat:'Unlocks deep heat tolerance'}, {id:'pressure',name:'Pressure resistance',desc:'Pressure-rated pipe joints and seals.',base:1200,stat:'Unlocks high-pressure strata'}, {id:'deep',name:'Deep drilling tech',desc:'Adaptive mud motor for mantle analogue.',base:2200,stat:'+50% deep-zone advance'}, {id:'scanner',name:'Geological scanner',desc:'Resolve deposits before they reach the bit.',base:780,stat:'Improves discovery yield'}
];
const milestones=[{d:100,title:'FIRST CONTACT',copy:'The first hundred meters are on record.',reward:250},{d:500,title:'HARD ROCK',copy:'A stronger bit is now available in the lab.',reward:350},{d:1000,title:'CARBON SEAM',copy:'Coal-bearing strata confirmed.',reward:500},{d:5000,title:'DEEP DRILLING',copy:'Advanced drilling research unlocked.',reward:900},{d:10000,title:'PAST THE CRUST',copy:'Deep-earth equipment research unlocked.',reward:1500},{d:100000,title:'MANTLE ANALOGUE',copy:'Mantle conditions simulated. Research grant approved.',reward:5000},{d:1000000,title:'OUTER CORE ANALOGUE',copy:'A landmark in fictional deep-earth operations.',reward:25000},{d:6371000,title:'INNER CORE',copy:'The Earth's inner core has been reached.',reward:100000}];
function save(){try{localStorage.setItem('earthcore-save',JSON.stringify(state))}catch{}}
function currentLayer(){let found=layers[0];for(const l of layers)if(state.depth>=l.d)found=l;return found}
function fmt(n){return Math.floor(n).toLocaleString('en-US')}
function updateHUD(){const l=currentLayer();$('#depth').textContent=state.depth<1000?state.depth.toFixed(1).padStart(5,'0'):fmt(state.depth);$('#layer').textContent=l.n;$('#money').textContent=fmt(state.money);$('#oil-value').textContent=Math.round(state.oil/state.capacity*100)+'%';$('#oil-bar').style.width=Math.max(0,state.oil/state.capacity*100)+'%';$('#oil-detail').textContent=state.can>0?'Container carried · '+Math.round(state.can)+' L':'Hydraulic oil · '+state.oil.toFixed(0)+' / '+state.capacity+' L';$('#temp').textContent=Math.round(18+state.depth*.018+(state.drilling?22:0));$('#drill-status').textContent=state.drilling?'DRILLING':'STANDBY';$('#drill-light').classList.toggle('active',state.drilling);$('#status-label').textContent=state.drilling?'RIG OPERATING':'SITE ONLINE';$('#status-detail').textContent=state.drilling?'Rotary drive · '+(state.depth<10000?'Nominal':'Deep zone'):'Rig control panel · Offline';
let obj='Inspect the drilling rig',hint='Walk to the control station';if(state.can>0){obj='Carry oil to the rig';hint='Climb the yellow access stairs and refill the tank'}else if(state.oil<24){obj='Restock hydraulic oil';hint='Visit the Lube Supply shop'}else if(state.depth===0){obj='Start the drilling sequence';hint='Inspect the rig control station'}else if(state.drilling){obj='Monitor the bore';hint='Drilling advances while the rig is running'}else{obj='Continue the bore';hint='Restart at the rig control station'}$('#objective-text').textContent=obj;$('#objective-hint').textContent=hint}
function announce(text){const el=$('#toast');el.textContent=text;el.style.opacity='1';clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.style.opacity='0',2800)}
function milestoneCheck(){for(const m of milestones){if(state.depth>=m.d&&!state.milestones.includes(m.d)){state.milestones.push(m.d);state.money+=m.reward;$('#milestone-title').textContent=m.title;$('#milestone-copy').textContent=m.copy;$('#milestone-reward').textContent='+$'+fmt(m.reward);const el=$('#milestone');el.classList.add('show');setTimeout(()=>el.classList.remove('show'),5600);announce('Research milestone logged · '+m.title);save()}}}
function discover(){const d=state.depth;let pool=resources.slice(0,3);if(d>1000)pool=resources.slice(0,4);if(d>4000)pool=resources.slice(1,5);if(d>6000)pool=resources.slice(3);if(d>10000)pool=resources.slice(4);if(state.upgrades.scanner)pool=pool.concat(resources.slice(-2));const pick=pool[Math.floor(Math.random()*pool.length)];const qty=1+Math.floor(Math.random()*(state.upgrades.scanner?4:3));state.resources[pick[0]]+=qty;if(!state.discovered.includes(currentLayer().n)){state.discovered.push(currentLayer().n);announce('GEOLOGICAL DISCOVERY · '+currentLayer().n)}else announce('CORE SAMPLE · '+qty+' '+pick[0].toUpperCase());save()}
function audioStart(){if(!soundOn)return;try{audioCtx??=new AudioContext();audioCtx.resume();if(engineOsc)return;engineOsc=audioCtx.createOscillator();const gain=audioCtx.createGain();engineOsc.type='sawtooth';engineOsc.frequency.value=47;gain.gain.value=.018;engineOsc.connect(gain);gain.connect(audioCtx.destination);engineOsc.start()}catch{}}
function audioStop(){if(engineOsc){try{engineOsc.stop()}catch{}engineOsc=null}}
function beep(freq=520,d=.08){if(!soundOn)return;try{audioCtx??=new AudioContext();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.frequency.value=freq;g.gain.setValueAtTime(.035,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+d);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+d)}catch{}}
function modal(title,kicker,html){modalOpen=true;$('#modal').innerHTML=`<div class="modal-head"><div><span class="eyebrow">${kicker}</span><h2>${title}</h2></div><button class="close-modal" aria-label="Close">×</button></div>${html}`;$('#modal-backdrop').classList.add('open');$('#modal .close-modal').onclick=closeModal;$('#modal-backdrop').onclick=e=>{if(e.target.id==='modal-backdrop')closeModal()};document.exitPointerLock?.();}
function closeModal(){modalOpen=false;$('#modal-backdrop').classList.remove('open');$('#modal').innerHTML='';if(!isMobile())renderer.domElement.requestPointerLock?.()}
function isMobile(){return matchMedia('(pointer:coarse)').matches||innerWidth<760}
function shopPanel(){const oils=[{name:'Field can · 20 L',amount:20,cost:140,desc:'Portable sealed can. One-person carry.'},{name:'Drum · 50 L',amount:50,cost:300,desc:'Heavy-duty drum. Efficient for long runs.'}];modal('Lube supply','SUPPLY DEPOT · AUTHORIZED PURCHASE',`<p class="modal-copy">The shop attendant checks each container out to your field account. You must carry it to the rig and pour it into the elevated reservoir by hand.</p><div class="card-grid">${oils.map((o,i)=>`<article class="item-card"><h3>${o.name}</h3><p>${o.desc}</p><div class="item-meta"><span>${o.amount} L</span><span>$${o.cost}</span></div><button class="action-button" data-buy="${i}" ${state.can>0?'disabled':''}>${state.can>0?'CONTAINER ALREADY CARRIED':'PURCHASE & CARRY'}</button></article>`).join('')}</div><div class="modal-footer"><span>ACCOUNT BALANCE</span><b>$${fmt(state.money)}</b></div>`);$('#modal [data-buy="0"]').onclick=()=>buyOil(20,140);$('#modal [data-buy="1"]').onclick=()=>buyOil(50,300)}
function buyOil(amount,cost){if(state.money<cost){announce('Insufficient credits. Sell recovered samples in the lab.');return}if(state.can>0){announce('Return the carried container to the rig first.');return}state.money-=cost;state.can=amount;showCan(true);beep(680);save();updateHUD();shopPanel();announce('Oil checked out · carry it to the rig')}
function showCan(on){heldCan.visible=on}
const heldCan=new THREE.Group();const canBody=new THREE.Mesh(new THREE.CylinderGeometry(.13,.16,.43,12),new THREE.MeshStandardMaterial({color:0xd9a22c,metalness:.35,roughness:.5}));heldCan.add(canBody);const canTop=new THREE.Mesh(new THREE.CylinderGeometry(.07,.07,.07,12),mats.darkSteel);canTop.position.y=.24;heldCan.add(canTop);const canLabel=new THREE.Mesh(new THREE.BoxGeometry(.19,.12,.012),new THREE.MeshBasicMaterial({color:0x263839}));canLabel.position.set(0,.01,.15);heldCan.add(canLabel);heldCan.position.set(.35,-.32,-.7);camera.add(heldCan);scene.add(camera);heldCan.visible=state.can>0;
function upgradesPanel(){const rows=upgrades.map(u=>{const lv=state.upgrades[u.id],price=Math.round(u.base*Math.pow(1.58,lv));const locked=(u.id==='deep'&&state.depth<5000)||(u.id==='heat'&&state.depth<5000)||(u.id==='pressure'&&state.depth<10000);return `<article class="item-card"><div class="item-meta"><span>LEVEL ${lv} → ${lv+1}</span><span>$${fmt(price)}</span></div><h3>${u.name}</h3><p>${u.desc}<br><b style="color:#c8f36a">${u.stat}</b></p><button class="action-button ${locked?'secondary':''}" data-upgrade="${u.id}" ${locked||state.money<price?'disabled':''}>${locked?'REQUIRES DEEPER BORE':state.money<price?'INSUFFICIENT CREDITS':'INSTALL UPGRADE'}</button></article>`}).join('');modal('Research & upgrades','FIELD SCIENCE LAB · K-9 PROGRAM',`<p class="modal-copy">Research grants are funded by recovered core samples. Each installation immediately modifies the rig. Deep-earth systems require a logged bore milestone.</p><div class="stat-grid"><div class="stat-box"><span>DRILL POWER</span><b>${100+state.upgrades.power*18}%</b></div><div class="stat-box"><span>OIL CAPACITY</span><b>${state.capacity} L</b></div><div class="stat-box"><span>ADVANCE RATE</span><b>${(1+state.upgrades.speed*.15+state.upgrades.engine*.06).toFixed(2)}×</b></div></div><div class="card-grid">${rows}</div><div class="modal-footer"><span>RESEARCH ACCOUNT</span><b>$${fmt(state.money)}</b></div>`);$('#modal').querySelectorAll('[data-upgrade]').forEach(btn=>btn.onclick=()=>buyUpgrade(btn.dataset.upgrade))}
function buyUpgrade(id){const u=upgrades.find(a=>a.id===id),lv=state.upgrades[id],cost=Math.round(u.base*Math.pow(1.58,lv));if(state.money<cost)return;state.money-=cost;state.upgrades[id]++;if(id==='capacity'){state.capacity+=35;state.oil=Math.min(state.capacity,state.oil+35)}if(id==='power'||id==='speed'||id==='engine')announce('Upgrade installed · '+u.name);beep(790,.13);save();updateHUD();upgradesPanel()}

function rigPanel(){const pct=Math.round(state.oil/state.capacity*100),perf=(100+state.upgrades.power*18),canStart=state.oil>2;modal('K-9 rotary bore','RIG CONTROL · FIELD CHECK',`<p class="modal-copy">Mechanical interlocks: <b style="color:${canStart?'#c8f36a':'#ef9e69'}">${canStart?'READY':'LOW OIL — REFILL REQUIRED'}</b>. Check lubrication, inspect the downhole temperature, then engage the rotary drive.</p><div class="stat-grid"><div class="stat-box"><span>RESERVOIR</span><b>${state.oil.toFixed(1)} / ${state.capacity} L</b></div><div class="stat-box"><span>BIT CONDITION</span><b>${Math.max(28,100-state.depth*.0004+state.upgrades.durability*8).toFixed(0)}%</b></div><div class="stat-box"><span>DRILL POWER</span><b>${perf}%</b></div></div><div class="item-card"><div class="item-meta"><span>FIELD INSPECTION</span><span>${state.drilling?'LIVE':'COMPLETE'}</span></div><p>Hydraulic manifold ${pct>12?'nominal':'below safe pressure'} · cooling loop ${state.upgrades.cooling?'upgraded':'standard'} · downhole pressure ${Math.max(1,(1+state.depth/4800)).toFixed(1)} MPa (gameplay model).</p><button class="action-button" id="drill-toggle" ${!state.drilling&&!canStart?'disabled':''}>${state.drilling?'DISENGAGE ROTARY DRIVE':'START DRILLING SEQUENCE'}</button></div><div class="modal-footer"><span>EST. ADVANCE</span><b>${(1+state.upgrades.speed*.15+state.upgrades.engine*.06).toFixed(2)} m/s · ${pct}% oil</b></div>`);$('#drill-toggle').onclick=toggleDrill}
function toggleDrill(){if(!state.drilling&&state.oil<=2){announce('Safe start interlock · refill the reservoir first');return}state.drilling=!state.drilling;if(state.drilling){audioStart();beep(170,.3);announce('Rotary drive engaged · monitoring bore')}else{audioStop();beep(300);announce('Drill sequence stopped')}save();updateHUD();rigPanel()}
function refillPanel(){if(state.can<=0){modal('Reservoir service','RIG MAINTENANCE · MANUAL REFILL',`<p class="modal-copy">No oil container is being carried. The reservoir can only be serviced at this elevated fill point. Return to the Lube Supply shop to check out a field container.</p><div class="stat-grid"><div class="stat-box"><span>OIL LEVEL</span><b>${state.oil.toFixed(1)} L</b></div><div class="stat-box"><span>CAPACITY</span><b>${state.capacity} L</b></div><div class="stat-box"><span>RIG STATUS</span><b>${state.drilling?'RUNNING':'OFFLINE'}</b></div></div>`);return}if(state.drilling){state.drilling=false;audioStop()}const liters=Math.min(state.can,state.capacity-state.oil);modal('Reservoir service','RIG MAINTENANCE · MANUAL REFILL',`<p class="modal-copy">Remove the pressure cap and pour the carried container into the hydraulic tank. Transfer is physical and only available at the rig's elevated fill point.</p><div class="stat-grid"><div class="stat-box"><span>CONTAINER</span><b>${state.can} L carried</b></div><div class="stat-box"><span>SPACE AVAILABLE</span><b>${(state.capacity-state.oil).toFixed(1)} L</b></div><div class="stat-box"><span>TRANSFER</span><b>${liters.toFixed(0)} L</b></div></div><button class="action-button" id="pour-oil" ${liters<=0?'disabled':''}>${liters<=0?'RESERVOIR FULL':'OPEN CAP & POUR OIL'}</button>`);$('#pour-oil').onclick=()=>{state.oil+=liters;state.can=0;showCan(false);beep(340,.22);announce(`${liters.toFixed(0)} L transferred · reservoir ${Math.round(state.oil/state.capacity*100)}%`);save();updateHUD();refillPanel()}}
function inventoryPanel(){const rows=resources.map(([name,value])=>`<div class="inventory-row"><span>${name}</span><small>${state.resources[name]} units · $${value}/unit</small><strong>$${fmt(state.resources[name]*value)}</strong><button data-sell="${name}" ${state.resources[name]<=0?'disabled':''}>SELL</button></div>`).join('');modal('Recovered samples','FIELD INVENTORY · SAMPLE LOCKER',`<p class="modal-copy">Samples must be returned to the science lab for assay and credit. Sale value reflects current research demand.</p>${rows}<div class="modal-footer"><span>ACCOUNT BALANCE</span><b>$${fmt(state.money)}</b></div>`);$('#modal').querySelectorAll('[data-sell]').forEach(b=>b.onclick=()=>sellResource(b.dataset.sell))}
function sellResource(name){const v=resources.find(r=>r[0]===name)?.[1]||0,n=state.resources[name];if(!n)return;state.money+=n*v;state.resources[name]=0;beep(620);save();updateHUD();inventoryPanel();announce(`Samples assayed · +$${fmt(n*v)}`)}
function geologyPanel(){const rows=layers.map(l=>`<div class="inventory-row"><span>${l.n}${l.n.includes('*')?' · gameplay scale':''}</span><small>${fmt(l.d)} m · ${l.m}</small><strong>${state.discovered.includes(l.n)?'LOGGED':state.depth>=l.d?'NEAR':'LOCKED'}</strong></div>`).join('');modal('Geology archive','SUBSURFACE STRATIGRAPHY · ${fmt(state.depth)} M',`<p class="modal-copy">Depths beyond the continental crust are highly compressed for gameplay and represent a scientifically inspired fictional simulation. Actual Earth layers are not physically reachable by this rig.</p>${rows}`)}
const camFeeds=[{name:'RIG FLOOR',pos:[9,7,12],look:[0,3,0]},{name:'SUPPLY DEPOT',pos:[20,5,8],look:[13,1,2]},{name:'LAB EXTERIOR',pos:[-1,5,-5],look:[8,1,-6]},{name:'BORE MOUTH',pos:[-8,6,5],look:[0,1,0]},{name:'WAREHOUSE',pos:[-20,7,3],look:[-12,1,-7]}].map(d=>{const c=new THREE.PerspectiveCamera(60,16/9,.1,160);c.position.set(...d.pos);c.lookAt(...d.look);return {...d,camera:c}});let cameraIndex=0,feedClock=0,feedTarget=new THREE.WebGLRenderTarget(320,180),feedPixels=new Uint8Array(320*180*4);
function monitorPanel(){cameraIndex=0;modal('Perimeter monitoring','SECURITY NETWORK · 5 CAMERAS',`<div class="camera-screen"><canvas id="feed-canvas" width="320" height="180" style="width:100%;height:100%;object-fit:cover"></canvas><span style="position:absolute;left:12px;top:10px;text-shadow:0 2px 6px #000">● LIVE · <b id="feed-name">RIG FLOOR</b></span><span style="position:absolute;right:12px;bottom:10px;font-size:9px;text-shadow:0 2px 6px #000">K9-SITE · 1080p</span></div><div class="camera-list">${camFeeds.map((c,i)=>`<button data-cam="${i}" class="${i===0?'selected':''}">CAM ${String(i+1).padStart(2,'0')}</button>`).join('')}</div><p class="modal-copy">Live security views from the facility perimeter. Select a camera feed.</p>`);$('#modal').querySelectorAll('[data-cam]').forEach(b=>b.onclick=()=>{cameraIndex=+b.dataset.cam;$('#feed-name').textContent=camFeeds[cameraIndex].name;$('#modal .camera-list .selected')?.classList.remove('selected');b.classList.add('selected')});feedClock=2}
function updateFeed(dt){if(!modalOpen||!$('#feed-canvas'))return;feedClock-=dt;if(feedClock>0)return;feedClock=.65;const c=camFeeds[cameraIndex].camera;renderer.setRenderTarget(feedTarget);renderer.render(scene,c);renderer.readRenderTargetPixels(feedTarget,0,0,320,180,feedPixels);renderer.setRenderTarget(null);const canvas=$('#feed-canvas'),ctx=canvas?.getContext('2d');if(!ctx)return;const img=ctx.createImageData(320,180);for(let y=0;y<180;y++)for(let x=0;x<320;x++){const s=((179-y)*320+x)*4,d=(y*320+x)*4;img.data[d]=feedPixels[s];img.data[d+1]=feedPixels[s+1];img.data[d+2]=feedPixels[s+2];img.data[d+3]=255}ctx.putImageData(img,0,0)}
function openLab(){modal('Field science lab','GEOLOGICAL RESEARCH · STATION 01',`<p class="modal-copy">Analyze recovered samples, tune the K-9 system, or inspect downhole stratigraphy. All deep-zone layers beyond the crust are represented as a compressed gameplay simulation.</p><div class="card-grid"><article class="item-card"><h3>Rig research terminal</h3><p>Install mechanical and efficiency upgrades using your research account.</p><button class="action-button" id="lab-upgrades">OPEN UPGRADES</button></article><article class="item-card"><h3>Sample assay station</h3><p>Turn recovered core samples into credits for oil and equipment.</p><button class="action-button secondary" id="lab-inventory">ASSAY & SELL SAMPLES</button></article><article class="item-card"><h3>Stratigraphy database</h3><p>Review known formations and discoveries from the current bore.</p><button class="action-button secondary" id="lab-geology">VIEW GEOLOGY LOG</button></article><article class="item-card"><h3>Security station</h3><p>Five live feeds cover the rig, supply store, lab, bore, and warehouse.</p><button class="action-button secondary" id="lab-cameras">OPEN CAMERA WALL</button></article></div>`);$('#lab-upgrades').onclick=upgradesPanel;$('#lab-inventory').onclick=inventoryPanel;$('#lab-geology').onclick=geologyPanel;$('#lab-cameras').onclick=monitorPanel}
const interactables=[{id:'console',name:'RIG CONTROL · INSPECT / OPERATE',pos:new THREE.Vector3(3.2,1.3,4.0),radius:2.6,run:rigPanel},{id:'shop',name:'LUBE SUPPLY · PURCHASE OIL',pos:new THREE.Vector3(13,1,5.2),radius:2.8,run:shopPanel},{id:'lab',name:'SCIENCE LAB · RESEARCH STATION',pos:new THREE.Vector3(8,1.4,-2.4),radius:2.8,run:openLab},{id:'lab2',name:'LAB SAMPLE ASSAY · SELL RESOURCES',pos:new THREE.Vector3(9.2,1.3,-3.5),radius:2.2,run:inventoryPanel},{id:'camera',name:'SECURITY MONITOR WALL',pos:new THREE.Vector3(6,1.3,-3.3),radius:2.4,run:monitorPanel},{id:'geology',name:'GEOLOGICAL DATABASE',pos:new THREE.Vector3(10,1.3,-3.4),radius:2.4,run:geologyPanel},{id:'refill',name:'ELEVATED OIL FILL · OPEN CAP',pos:new THREE.Vector3(2.85,2.4,-.3),radius:2.1,run:refillPanel}];

