import { chromium } from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright/index.mjs';
const browser=await chromium.launch({headless:true,args:['--use-gl=angle','--use-angle=swiftshader']});
const page=await browser.newPage({viewport:{width:1280,height:800},deviceScaleFactor:1});
const errors=[];page.on('pageerror',e=>errors.push(e.message));page.on('console',m=>{if(m.type()==='error')errors.push(m.text())});
await page.addInitScript(()=>localStorage.removeItem('earth-core-save'));
await page.goto('http://127.0.0.1:3000',{waitUntil:'networkidle'});
await page.locator('#begin-button').click();
const hold=async(key,ms)=>{await page.keyboard.down(key);await page.waitForTimeout(ms);await page.keyboard.up(key);await page.waitForTimeout(100)};
await hold('KeyW',420);
const prompt=await page.locator('#prompt-text').textContent();
await page.keyboard.press('KeyE');
await page.waitForTimeout(100);
const modalVisible=await page.locator('#modal-backdrop').isVisible();
const rigButtonVisible=await page.locator('#drill-toggle').isVisible().catch(()=>false);
console.log(JSON.stringify({prompt,modalVisible,rigButtonVisible,title:await page.locator('#modal h2').textContent().catch(()=>null),errors},null,2));
if(!modalVisible||!rigButtonVisible)throw new Error('Rig panel action is not visible');
await page.locator('#drill-toggle').click();
await page.waitForTimeout(2200);
const depth=await page.locator('#depth').textContent();
const status=await page.locator('#drill-status').textContent();
await page.screenshot({path:'/tmp/opencode/earth-core/latest.jpg',type:'jpeg',quality:84});
console.log(JSON.stringify({depth,status,drillButton:await page.locator('#drill-toggle').textContent(),errors},null,2));
await page.locator('.modal-close').click();
await page.waitForTimeout(100);
await page.keyboard.press('Escape');
await page.waitForTimeout(100);
await browser.close();

