import {chromium} from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright/index.mjs';
const b=await chromium.launch({headless:true,args:['--use-gl=angle','--use-angle=swiftshader']});const p=await b.newPage({viewport:{width:1280,height:800}});const errors=[];p.on('pageerror',e=>errors.push(e.message));
await p.addInitScript(()=>localStorage.setItem('earth-core-save',JSON.stringify({resources:{Basalt:2},money:1250})));
await p.goto('http://127.0.0.1:3000',{waitUntil:'networkidle'});await p.locator('#begin-button').click();
const hold=async(k,ms)=>{await p.keyboard.down(k);await p.waitForTimeout(ms);await p.keyboard.up(k);await p.waitForTimeout(100)};
await hold('KeyD',1400);const shopPrompt=await p.locator('#prompt-text').textContent();await p.keyboard.press('KeyE');await p.waitForTimeout(150);const shopVisible=await p.locator('#buy-can').isVisible().catch(()=>false);if(shopVisible)await p.locator('#buy-can').click();const checkout=await p.locator('#modal').innerText();
await p.keyboard.press('KeyI');await p.waitForTimeout(100);const sellButton=p.locator('[data-sell="Basalt"]');const sellVisible=await sellButton.isVisible().catch(()=>false);if(sellVisible)await sellButton.click();
const result={shopPrompt,shopVisible,checkout:s=>s,inventoryVisible:await p.locator('#modal h2').textContent().catch(()=>null),money:await p.locator('#money').textContent(),errors};
console.log(JSON.stringify(result,null,2));await b.close();
